#include <bits/stdc++.h>
using namespace std;

bool isValid(string num)
{
    if (num.size() > 1 && num[0] == '0')
        return false;
    return true;
}

int val(string a, int pos)
{
    if (pos < 0)
        return 0;
    return (a[pos] - '0');
}

string addString(string a, string b)
{
    string sum = "";
    int i = a.length() - 1;
    int j = b.length() - 1;
    int carry = 0;

    while (i >= 0 || j >= 0) {
        int t = val(a, i) + val(b, j) + carry;
        sum += (t % 10 + '0');
        carry = t / 10;
        i--;
        j--;
    }

    if (carry)
        sum += (carry + '0');

    reverse(sum.begin(), sum.end());
    return sum;
}

bool checkAddition(string a, string b, string c)
{
    if (!isValid(a) || !isValid(b))
        return false;

    string sum = addString(a, b);

    if (sum == c)
        return true;

    if (c.size() <= sum.size() || sum != c.substr(0, sum.size()))
        return false;
    else {
        return checkAddition(b, sum, c.substr(sum.size()));
    }
}

bool isAdditive(string &s)
{
    int n = s.length();

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= (n - i) / 2; j++) {
            if (checkAddition(s.substr(0, i), s.substr(i, j), s.substr(i + j)))
                return true;
        }
    }

    return false;
}

int main()
{
    string s = "235813";

    if (isAdditive(s))
        cout << "true" << endl;
    else
        cout << "false" << endl;

    return 0;
}

