void dfs(int pos, int n, int prevBit, int num, vector<int> &ans)
{
    if (pos == n)
    {
        ans.push_back(num);
        return;
    }

    dfs(pos + 1, n, 0, num << 1, ans);

    if (prevBit == 0)
    {
        dfs(pos + 1, n, 1, (num << 1) | 1, ans);
    }
}

